  "lesson": [
   {
    "f": "había · habías · habíamos + participio = antes de otra cosa pasada",
    "ex": "Cuando llegué, ya [había empezado]. Nunca [había visto] algo así."
   },
   {
    "f": "dice que + presente · dijo que: estoy → estaba, voy a → iba a, llamé → había llamado, lloverá → llovería",
    "ex": "Dice que [viene]. Dijo que [estaba] cansado."
   },
   {
    "f": "preguntar si (sí o no) · preguntar qué / dónde / cuánto / cómo…",
    "ex": "Me preguntó [si] tenía hijos. Me preguntó [dónde] vivía."
   },
   {
    "f": "pedir / decir que + subjuntivo · en pasado, presente o imperfecto de subjuntivo: que lo llame / llamara",
    "ex": "Me pidió que lo [llame]. Le dije que [espere]."
   }
  ],
